CREATE TABLE "api_key_outer_auth" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "api_key_outer_id" bigint NOT NULL,
  "flag" varchar(255) NOT NULL,
  "created_at" datetime
);

